PRAGMA foreign_keys=ON;
BEGIN TRANSACTION;
INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk8-01','HSK8-01','HSK 8 · Đề 01','hsk','HSK 8',90,'published',1,'Đề luyện HSK 8 số 01 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk8-01-q01','seed-hsk8-01',1,'single_choice','Pinyin phù hợp với “辨析” là phương án nào?','Pinyin của “辨析” là “biànxī”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “phân biệt và phân tích”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-01-q02','seed-hsk8-01',2,'single_choice','Chọn từ Hán ngữ có nghĩa “biểu trưng”.','Từ phù hợp là “表征”, đọc là biǎozhēng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-01-q03','seed-hsk8-01',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “取向 — qǔxiàng”, nghĩa là “định hướng”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-01-q04','seed-hsk8-01',4,'single_choice','Từ “回应” gần nghĩa nhất với phương án nào?','“回应” (huíyìng) có nghĩa là “phản hồi”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 8.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-01-q05','seed-hsk8-01',5,'single_choice','Pinyin phù hợp với “诠释” là phương án nào?','Pinyin của “诠释” là “quánshì”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “diễn giải”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-01-q06','seed-hsk8-01',6,'single_choice','Chọn từ Hán ngữ có nghĩa “cân nhắc”.','Từ phù hợp là “权衡”, đọc là quánhéng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-01-q07','seed-hsk8-01',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “外延 — wàiyán”, nghĩa là “ngoại diên”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-01-q08','seed-hsk8-01',8,'single_choice','Từ “衔接” gần nghĩa nhất với phương án nào?','“衔接” (xiánjiē) có nghĩa là “kết nối chuyển tiếp”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 8.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-01-q09','seed-hsk8-01',9,'single_choice','Pinyin phù hợp với “论证” là phương án nào?','Pinyin của “论证” là “lùnzhèng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “lập luận chứng minh”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-01-q10','seed-hsk8-01',10,'single_choice','Chọn từ Hán ngữ có nghĩa “nhu cầu/đòi hỏi”.','Từ phù hợp là “诉求”, đọc là sùqiú. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-01-q11','seed-hsk8-01',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “范式 — fànshì”, nghĩa là “mô thức”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-01-q12','seed-hsk8-01',12,'single_choice','Từ “推演” gần nghĩa nhất với phương án nào?','“推演” (tuīyǎn) có nghĩa là “suy diễn”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 8.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-01-q13','seed-hsk8-01',13,'single_choice','Pinyin phù hợp với “抽象” là phương án nào?','Pinyin của “抽象” là “chōuxiàng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “trừu tượng”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-01-q14','seed-hsk8-01',14,'single_choice','Chọn từ Hán ngữ có nghĩa “phù hợp”.','Từ phù hợp là “契合”, đọc là qìhé. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-01-q15','seed-hsk8-01',15,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “脉络 — màiluò”, nghĩa là “mạch phát triển”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-01-q16','seed-hsk8-01',16,'single_choice','Từ “审视” gần nghĩa nhất với phương án nào?','“审视” (shěnshì) có nghĩa là “xem xét kỹ”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 8.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-01-q17','seed-hsk8-01',17,'single_choice','Pinyin phù hợp với “介入” là phương án nào?','Pinyin của “介入” là “jièrù”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “can thiệp”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-01-q18','seed-hsk8-01',18,'single_choice','Chọn từ Hán ngữ có nghĩa “kiến tạo”.','Từ phù hợp là “建构”, đọc là jiàngòu. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-01-q19','seed-hsk8-01',19,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “边界 — biānjiè”, nghĩa là “ranh giới”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-01-q20','seed-hsk8-01',20,'single_choice','Từ “内涵” gần nghĩa nhất với phương án nào?','“内涵” (nèihán) có nghĩa là “nội hàm”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 8.',NULL,NULL,0,1,'',datetime('now')),
