INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk8-02','HSK8-02','HSK 8 · Đề 02','hsk','HSK 8',90,'published',1,'Đề luyện HSK 8 số 02 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk8-02-q01','seed-hsk8-02',1,'single_choice','Pinyin phù hợp với “诉求” là phương án nào?','Pinyin của “诉求” là “sùqiú”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “nhu cầu/đòi hỏi”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-02-q02','seed-hsk8-02',2,'single_choice','Chọn từ Hán ngữ có nghĩa “mô thức”.','Từ phù hợp là “范式”, đọc là fànshì. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-02-q03','seed-hsk8-02',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “推演 — tuīyǎn”, nghĩa là “suy diễn”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-02-q04','seed-hsk8-02',4,'single_choice','Từ “抽象” gần nghĩa nhất với phương án nào?','“抽象” (chōuxiàng) có nghĩa là “trừu tượng”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 8.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-02-q05','seed-hsk8-02',5,'single_choice','Pinyin phù hợp với “契合” là phương án nào?','Pinyin của “契合” là “qìhé”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “phù hợp”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-02-q06','seed-hsk8-02',6,'single_choice','Chọn từ Hán ngữ có nghĩa “mạch phát triển”.','Từ phù hợp là “脉络”, đọc là màiluò. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-02-q07','seed-hsk8-02',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “审视 — shěnshì”, nghĩa là “xem xét kỹ”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-02-q08','seed-hsk8-02',8,'single_choice','Từ “介入” gần nghĩa nhất với phương án nào?','“介入” (jièrù) có nghĩa là “can thiệp”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 8.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-02-q09','seed-hsk8-02',9,'single_choice','Pinyin phù hợp với “建构” là phương án nào?','Pinyin của “建构” là “jiàngòu”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “kiến tạo”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-02-q10','seed-hsk8-02',10,'single_choice','Chọn từ Hán ngữ có nghĩa “ranh giới”.','Từ phù hợp là “边界”, đọc là biānjiè. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-02-q11','seed-hsk8-02',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “内涵 — nèihán”, nghĩa là “nội hàm”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-02-q12','seed-hsk8-02',12,'single_choice','Từ “辨析” gần nghĩa nhất với phương án nào?','“辨析” (biànxī) có nghĩa là “phân biệt và phân tích”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 8.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-02-q13','seed-hsk8-02',13,'single_choice','Pinyin phù hợp với “表征” là phương án nào?','Pinyin của “表征” là “biǎozhēng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “biểu trưng”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-02-q14','seed-hsk8-02',14,'single_choice','Chọn từ Hán ngữ có nghĩa “định hướng”.','Từ phù hợp là “取向”, đọc là qǔxiàng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
