('seed-hsk8-02-q17','seed-hsk8-02',17,'single_choice','Pinyin phù hợp với “权衡” là phương án nào?','Pinyin của “权衡” là “quánhéng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “cân nhắc”.',NULL,NULL,0,1,'',datetime('now')),
