INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk8-03','HSK8-03','HSK 8 · Đề 03','hsk','HSK 8',90,'published',1,'Đề luyện HSK 8 số 03 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk8-03-q01','seed-hsk8-03',1,'single_choice','Pinyin phù hợp với “边界” là phương án nào?','Pinyin của “边界” là “biānjiè”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “ranh giới”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-03-q02','seed-hsk8-03',2,'single_choice','Chọn từ Hán ngữ có nghĩa “nội hàm”.','Từ phù hợp là “内涵”, đọc là nèihán. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-03-q03','seed-hsk8-03',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “辨析 — biànxī”, nghĩa là “phân biệt và phân tích”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-03-q04','seed-hsk8-03',4,'single_choice','Từ “表征” gần nghĩa nhất với phương án nào?','“表征” (biǎozhēng) có nghĩa là “biểu trưng”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 8.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-03-q05','seed-hsk8-03',5,'single_choice','Pinyin phù hợp với “取向” là phương án nào?','Pinyin của “取向” là “qǔxiàng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “định hướng”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-03-q06','seed-hsk8-03',6,'single_choice','Chọn từ Hán ngữ có nghĩa “phản hồi”.','Từ phù hợp là “回应”, đọc là huíyìng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-03-q07','seed-hsk8-03',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “诠释 — quánshì”, nghĩa là “diễn giải”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-03-q08','seed-hsk8-03',8,'single_choice','Từ “权衡” gần nghĩa nhất với phương án nào?','“权衡” (quánhéng) có nghĩa là “cân nhắc”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 8.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-03-q09','seed-hsk8-03',9,'single_choice','Pinyin phù hợp với “外延” là phương án nào?','Pinyin của “外延” là “wàiyán”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “ngoại diên”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-03-q10','seed-hsk8-03',10,'single_choice','Chọn từ Hán ngữ có nghĩa “kết nối chuyển tiếp”.','Từ phù hợp là “衔接”, đọc là xiánjiē. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-03-q11','seed-hsk8-03',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “论证 — lùnzhèng”, nghĩa là “lập luận chứng minh”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-03-q12','seed-hsk8-03',12,'single_choice','Từ “诉求” gần nghĩa nhất với phương án nào?','“诉求” (sùqiú) có nghĩa là “nhu cầu/đòi hỏi”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 8.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-03-q13','seed-hsk8-03',13,'single_choice','Pinyin phù hợp với “范式” là phương án nào?','Pinyin của “范式” là “fànshì”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “mô thức”.',NULL,NULL,0,1,'',datetime('now')),
