INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk8-04','HSK8-04','HSK 8 · Đề 04','hsk','HSK 8',90,'published',1,'Đề luyện HSK 8 số 04 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk8-04-q01','seed-hsk8-04',1,'single_choice','Pinyin phù hợp với “衔接” là phương án nào?','Pinyin của “衔接” là “xiánjiē”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “kết nối chuyển tiếp”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-04-q02','seed-hsk8-04',2,'single_choice','Chọn từ Hán ngữ có nghĩa “lập luận chứng minh”.','Từ phù hợp là “论证”, đọc là lùnzhèng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-04-q03','seed-hsk8-04',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “诉求 — sùqiú”, nghĩa là “nhu cầu/đòi hỏi”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-04-q04','seed-hsk8-04',4,'single_choice','Từ “范式” gần nghĩa nhất với phương án nào?','“范式” (fànshì) có nghĩa là “mô thức”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 8.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-04-q05','seed-hsk8-04',5,'single_choice','Pinyin phù hợp với “推演” là phương án nào?','Pinyin của “推演” là “tuīyǎn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “suy diễn”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-04-q06','seed-hsk8-04',6,'single_choice','Chọn từ Hán ngữ có nghĩa “trừu tượng”.','Từ phù hợp là “抽象”, đọc là chōuxiàng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-04-q07','seed-hsk8-04',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “契合 — qìhé”, nghĩa là “phù hợp”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-04-q08','seed-hsk8-04',8,'single_choice','Từ “脉络” gần nghĩa nhất với phương án nào?','“脉络” (màiluò) có nghĩa là “mạch phát triển”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 8.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-04-q09','seed-hsk8-04',9,'single_choice','Pinyin phù hợp với “审视” là phương án nào?','Pinyin của “审视” là “shěnshì”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “xem xét kỹ”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-04-q10','seed-hsk8-04',10,'single_choice','Chọn từ Hán ngữ có nghĩa “can thiệp”.','Từ phù hợp là “介入”, đọc là jièrù. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-04-q11','seed-hsk8-04',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “建构 — jiàngòu”, nghĩa là “kiến tạo”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-04-q12','seed-hsk8-04',12,'single_choice','Từ “边界” gần nghĩa nhất với phương án nào?','“边界” (biānjiè) có nghĩa là “ranh giới”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 8.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-04-q13','seed-hsk8-04',13,'single_choice','Pinyin phù hợp với “内涵” là phương án nào?','Pinyin của “内涵” là “nèihán”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “nội hàm”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-04-q14','seed-hsk8-04',14,'single_choice','Chọn từ Hán ngữ có nghĩa “phân biệt và phân tích”.','Từ phù hợp là “辨析”, đọc là biànxī. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-04-q15','seed-hsk8-04',15,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “表征 — biǎozhēng”, nghĩa là “biểu trưng”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-04-q16','seed-hsk8-04',16,'single_choice','Từ “取向” gần nghĩa nhất với phương án nào?','“取向” (qǔxiàng) có nghĩa là “định hướng”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 8.',NULL,NULL,0,1,'',datetime('now')),
