INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk8-05','HSK8-05','HSK 8 · Đề 05','hsk','HSK 8',90,'published',1,'Đề luyện HSK 8 số 05 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk8-05-q01','seed-hsk8-05',1,'single_choice','Pinyin phù hợp với “介入” là phương án nào?','Pinyin của “介入” là “jièrù”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “can thiệp”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-05-q02','seed-hsk8-05',2,'single_choice','Chọn từ Hán ngữ có nghĩa “kiến tạo”.','Từ phù hợp là “建构”, đọc là jiàngòu. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-05-q03','seed-hsk8-05',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “边界 — biānjiè”, nghĩa là “ranh giới”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-05-q04','seed-hsk8-05',4,'single_choice','Từ “内涵” gần nghĩa nhất với phương án nào?','“内涵” (nèihán) có nghĩa là “nội hàm”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 8.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-05-q05','seed-hsk8-05',5,'single_choice','Pinyin phù hợp với “辨析” là phương án nào?','Pinyin của “辨析” là “biànxī”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “phân biệt và phân tích”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-05-q06','seed-hsk8-05',6,'single_choice','Chọn từ Hán ngữ có nghĩa “biểu trưng”.','Từ phù hợp là “表征”, đọc là biǎozhēng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-05-q07','seed-hsk8-05',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “取向 — qǔxiàng”, nghĩa là “định hướng”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-05-q08','seed-hsk8-05',8,'single_choice','Từ “回应” gần nghĩa nhất với phương án nào?','“回应” (huíyìng) có nghĩa là “phản hồi”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 8.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-05-q09','seed-hsk8-05',9,'single_choice','Pinyin phù hợp với “诠释” là phương án nào?','Pinyin của “诠释” là “quánshì”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “diễn giải”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-05-q10','seed-hsk8-05',10,'single_choice','Chọn từ Hán ngữ có nghĩa “cân nhắc”.','Từ phù hợp là “权衡”, đọc là quánhéng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-05-q11','seed-hsk8-05',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “外延 — wàiyán”, nghĩa là “ngoại diên”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-05-q12','seed-hsk8-05',12,'single_choice','Từ “衔接” gần nghĩa nhất với phương án nào?','“衔接” (xiánjiē) có nghĩa là “kết nối chuyển tiếp”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 8.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-05-q13','seed-hsk8-05',13,'single_choice','Pinyin phù hợp với “论证” là phương án nào?','Pinyin của “论证” là “lùnzhèng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “lập luận chứng minh”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-05-q14','seed-hsk8-05',14,'single_choice','Chọn từ Hán ngữ có nghĩa “nhu cầu/đòi hỏi”.','Từ phù hợp là “诉求”, đọc là sùqiú. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-05-q15','seed-hsk8-05',15,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “范式 — fànshì”, nghĩa là “mô thức”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
