('seed-hsk8-08-q22','seed-hsk8-08',22,'single_choice','Chọn từ Hán ngữ có nghĩa “diễn giải”.','Từ phù hợp là “诠释”, đọc là quánshì. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-08-q23','seed-hsk8-08',23,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “权衡 — quánhéng”, nghĩa là “cân nhắc”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-08-q24','seed-hsk8-08',24,'single_choice','Từ “外延” gần nghĩa nhất với phương án nào?','“外延” (wàiyán) có nghĩa là “ngoại diên”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 8.',NULL,NULL,0,1,'',datetime('now')),
