('seed-hsk8-09-q25','seed-hsk8-09',25,'single_choice','Pinyin phù hợp với “介入” là phương án nào?','Pinyin của “介入” là “jièrù”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “can thiệp”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-09-q26','seed-hsk8-09',26,'single_choice','Chọn từ Hán ngữ có nghĩa “kiến tạo”.','Từ phù hợp là “建构”, đọc là jiàngòu. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
