('seed-hsk8-10-q28','seed-hsk8-10',28,'single_choice','Từ “论证” gần nghĩa nhất với phương án nào?','“论证” (lùnzhèng) có nghĩa là “lập luận chứng minh”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 8.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-10-q29','seed-hsk8-10',29,'single_choice','Pinyin phù hợp với “诉求” là phương án nào?','Pinyin của “诉求” là “sùqiú”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “nhu cầu/đòi hỏi”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-10-q30','seed-hsk8-10',30,'single_choice','Chọn từ Hán ngữ có nghĩa “mô thức”.','Từ phù hợp là “范式”, đọc là fànshì. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-10-q31','seed-hsk8-10',31,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “推演 — tuīyǎn”, nghĩa là “suy diễn”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-10-q32','seed-hsk8-10',32,'single_choice','Từ “抽象” gần nghĩa nhất với phương án nào?','“抽象” (chōuxiàng) có nghĩa là “trừu tượng”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 8.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-10-q33','seed-hsk8-10',33,'single_choice','Pinyin phù hợp với “契合” là phương án nào?','Pinyin của “契合” là “qìhé”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “phù hợp”.',NULL,NULL,0,1,'',datetime('now')),
