INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk8-11','HSK8-11','HSK 8 · Đề 11','hsk','HSK 8',90,'published',1,'Đề luyện HSK 8 số 11 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk8-11-q01','seed-hsk8-11',1,'single_choice','Pinyin phù hợp với “范式” là phương án nào?','Pinyin của “范式” là “fànshì”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “mô thức”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-11-q02','seed-hsk8-11',2,'single_choice','Chọn từ Hán ngữ có nghĩa “suy diễn”.','Từ phù hợp là “推演”, đọc là tuīyǎn. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-11-q03','seed-hsk8-11',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “抽象 — chōuxiàng”, nghĩa là “trừu tượng”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-11-q04','seed-hsk8-11',4,'single_choice','Từ “契合” gần nghĩa nhất với phương án nào?','“契合” (qìhé) có nghĩa là “phù hợp”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 8.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-11-q05','seed-hsk8-11',5,'single_choice','Pinyin phù hợp với “脉络” là phương án nào?','Pinyin của “脉络” là “màiluò”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “mạch phát triển”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-11-q06','seed-hsk8-11',6,'single_choice','Chọn từ Hán ngữ có nghĩa “xem xét kỹ”.','Từ phù hợp là “审视”, đọc là shěnshì. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-11-q07','seed-hsk8-11',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “介入 — jièrù”, nghĩa là “can thiệp”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-11-q08','seed-hsk8-11',8,'single_choice','Từ “建构” gần nghĩa nhất với phương án nào?','“建构” (jiàngòu) có nghĩa là “kiến tạo”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 8.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-11-q09','seed-hsk8-11',9,'single_choice','Pinyin phù hợp với “边界” là phương án nào?','Pinyin của “边界” là “biānjiè”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “ranh giới”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-11-q10','seed-hsk8-11',10,'single_choice','Chọn từ Hán ngữ có nghĩa “nội hàm”.','Từ phù hợp là “内涵”, đọc là nèihán. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-11-q11','seed-hsk8-11',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “辨析 — biànxī”, nghĩa là “phân biệt và phân tích”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-11-q12','seed-hsk8-11',12,'single_choice','Từ “表征” gần nghĩa nhất với phương án nào?','“表征” (biǎozhēng) có nghĩa là “biểu trưng”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 8.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-11-q13','seed-hsk8-11',13,'single_choice','Pinyin phù hợp với “取向” là phương án nào?','Pinyin của “取向” là “qǔxiàng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “định hướng”.',NULL,NULL,0,1,'',datetime('now')),
