('seed-hsk8-11-q31','seed-hsk8-11',31,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “辨析 — biànxī”, nghĩa là “phân biệt và phân tích”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-11-q32','seed-hsk8-11',32,'single_choice','Từ “表征” gần nghĩa nhất với phương án nào?','“表征” (biǎozhēng) có nghĩa là “biểu trưng”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 8.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-11-q33','seed-hsk8-11',33,'single_choice','Pinyin phù hợp với “取向” là phương án nào?','Pinyin của “取向” là “qǔxiàng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “định hướng”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-11-q34','seed-hsk8-11',34,'single_choice','Chọn từ Hán ngữ có nghĩa “phản hồi”.','Từ phù hợp là “回应”, đọc là huíyìng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-11-q35','seed-hsk8-11',35,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “诠释 — quánshì”, nghĩa là “diễn giải”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-11-q36','seed-hsk8-11',36,'single_choice','Từ “权衡” gần nghĩa nhất với phương án nào?','“权衡” (quánhéng) có nghĩa là “cân nhắc”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 8.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-11-q37','seed-hsk8-11',37,'single_choice','Pinyin phù hợp với “外延” là phương án nào?','Pinyin của “外延” là “wàiyán”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “ngoại diên”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-11-q38','seed-hsk8-11',38,'single_choice','Chọn từ Hán ngữ có nghĩa “kết nối chuyển tiếp”.','Từ phù hợp là “衔接”, đọc là xiánjiē. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-11-q39','seed-hsk8-11',39,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “论证 — lùnzhèng”, nghĩa là “lập luận chứng minh”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-11-q40','seed-hsk8-11',40,'single_choice','Từ “诉求” gần nghĩa nhất với phương án nào?','“诉求” (sùqiú) có nghĩa là “nhu cầu/đòi hỏi”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 8.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-11-q41','seed-hsk8-11',41,'single_choice','Pinyin phù hợp với “范式” là phương án nào?','Pinyin của “范式” là “fànshì”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “mô thức”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-11-q42','seed-hsk8-11',42,'single_choice','Chọn từ Hán ngữ có nghĩa “suy diễn”.','Từ phù hợp là “推演”, đọc là tuīyǎn. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-11-q43','seed-hsk8-11',43,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “抽象 — chōuxiàng”, nghĩa là “trừu tượng”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-11-q44','seed-hsk8-11',44,'single_choice','Từ “契合” gần nghĩa nhất với phương án nào?','“契合” (qìhé) có nghĩa là “phù hợp”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 8.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-11-q45','seed-hsk8-11',45,'single_choice','Pinyin phù hợp với “脉络” là phương án nào?','Pinyin của “脉络” là “màiluò”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “mạch phát triển”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-11-q46','seed-hsk8-11',46,'single_choice','Chọn từ Hán ngữ có nghĩa “xem xét kỹ”.','Từ phù hợp là “审视”, đọc là shěnshì. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
