INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk8-12','HSK8-12','HSK 8 · Đề 12','hsk','HSK 8',90,'published',1,'Đề luyện HSK 8 số 12 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk8-12-q01','seed-hsk8-12',1,'single_choice','Pinyin phù hợp với “内涵” là phương án nào?','Pinyin của “内涵” là “nèihán”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “nội hàm”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-12-q02','seed-hsk8-12',2,'single_choice','Chọn từ Hán ngữ có nghĩa “phân biệt và phân tích”.','Từ phù hợp là “辨析”, đọc là biànxī. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-12-q03','seed-hsk8-12',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “表征 — biǎozhēng”, nghĩa là “biểu trưng”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-12-q04','seed-hsk8-12',4,'single_choice','Từ “取向” gần nghĩa nhất với phương án nào?','“取向” (qǔxiàng) có nghĩa là “định hướng”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 8.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-12-q05','seed-hsk8-12',5,'single_choice','Pinyin phù hợp với “回应” là phương án nào?','Pinyin của “回应” là “huíyìng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “phản hồi”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-12-q06','seed-hsk8-12',6,'single_choice','Chọn từ Hán ngữ có nghĩa “diễn giải”.','Từ phù hợp là “诠释”, đọc là quánshì. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-12-q07','seed-hsk8-12',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “权衡 — quánhéng”, nghĩa là “cân nhắc”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-12-q08','seed-hsk8-12',8,'single_choice','Từ “外延” gần nghĩa nhất với phương án nào?','“外延” (wàiyán) có nghĩa là “ngoại diên”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 8.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-12-q09','seed-hsk8-12',9,'single_choice','Pinyin phù hợp với “衔接” là phương án nào?','Pinyin của “衔接” là “xiánjiē”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “kết nối chuyển tiếp”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-12-q10','seed-hsk8-12',10,'single_choice','Chọn từ Hán ngữ có nghĩa “lập luận chứng minh”.','Từ phù hợp là “论证”, đọc là lùnzhèng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
