('seed-hsk8-12-q34','seed-hsk8-12',34,'single_choice','Chọn từ Hán ngữ có nghĩa “trừu tượng”.','Từ phù hợp là “抽象”, đọc là chōuxiàng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-12-q35','seed-hsk8-12',35,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “契合 — qìhé”, nghĩa là “phù hợp”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-12-q36','seed-hsk8-12',36,'single_choice','Từ “脉络” gần nghĩa nhất với phương án nào?','“脉络” (màiluò) có nghĩa là “mạch phát triển”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 8.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-12-q37','seed-hsk8-12',37,'single_choice','Pinyin phù hợp với “审视” là phương án nào?','Pinyin của “审视” là “shěnshì”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “xem xét kỹ”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-12-q38','seed-hsk8-12',38,'single_choice','Chọn từ Hán ngữ có nghĩa “can thiệp”.','Từ phù hợp là “介入”, đọc là jièrù. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-12-q39','seed-hsk8-12',39,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “建构 — jiàngòu”, nghĩa là “kiến tạo”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-12-q40','seed-hsk8-12',40,'single_choice','Từ “边界” gần nghĩa nhất với phương án nào?','“边界” (biānjiè) có nghĩa là “ranh giới”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 8.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-12-q41','seed-hsk8-12',41,'single_choice','Pinyin phù hợp với “内涵” là phương án nào?','Pinyin của “内涵” là “nèihán”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “nội hàm”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-12-q42','seed-hsk8-12',42,'single_choice','Chọn từ Hán ngữ có nghĩa “phân biệt và phân tích”.','Từ phù hợp là “辨析”, đọc là biànxī. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-12-q43','seed-hsk8-12',43,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “表征 — biǎozhēng”, nghĩa là “biểu trưng”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-12-q44','seed-hsk8-12',44,'single_choice','Từ “取向” gần nghĩa nhất với phương án nào?','“取向” (qǔxiàng) có nghĩa là “định hướng”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 8.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-12-q45','seed-hsk8-12',45,'single_choice','Pinyin phù hợp với “回应” là phương án nào?','Pinyin của “回应” là “huíyìng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “phản hồi”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-12-q46','seed-hsk8-12',46,'single_choice','Chọn từ Hán ngữ có nghĩa “diễn giải”.','Từ phù hợp là “诠释”, đọc là quánshì. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-12-q47','seed-hsk8-12',47,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “权衡 — quánhéng”, nghĩa là “cân nhắc”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-12-q48','seed-hsk8-12',48,'single_choice','Từ “外延” gần nghĩa nhất với phương án nào?','“外延” (wàiyán) có nghĩa là “ngoại diên”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 8.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-12-q49','seed-hsk8-12',49,'single_choice','Pinyin phù hợp với “衔接” là phương án nào?','Pinyin của “衔接” là “xiánjiē”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “kết nối chuyển tiếp”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-12-q50','seed-hsk8-12',50,'single_choice','Chọn từ Hán ngữ có nghĩa “lập luận chứng minh”.','Từ phù hợp là “论证”, đọc là lùnzhèng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now'));
