INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk8-13','HSK8-13','HSK 8 · Đề 13','hsk','HSK 8',90,'published',1,'Đề luyện HSK 8 số 13 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk8-13-q01','seed-hsk8-13',1,'single_choice','Pinyin phù hợp với “论证” là phương án nào?','Pinyin của “论证” là “lùnzhèng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “lập luận chứng minh”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-13-q02','seed-hsk8-13',2,'single_choice','Chọn từ Hán ngữ có nghĩa “nhu cầu/đòi hỏi”.','Từ phù hợp là “诉求”, đọc là sùqiú. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-13-q03','seed-hsk8-13',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “范式 — fànshì”, nghĩa là “mô thức”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-13-q04','seed-hsk8-13',4,'single_choice','Từ “推演” gần nghĩa nhất với phương án nào?','“推演” (tuīyǎn) có nghĩa là “suy diễn”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 8.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-13-q05','seed-hsk8-13',5,'single_choice','Pinyin phù hợp với “抽象” là phương án nào?','Pinyin của “抽象” là “chōuxiàng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “trừu tượng”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-13-q06','seed-hsk8-13',6,'single_choice','Chọn từ Hán ngữ có nghĩa “phù hợp”.','Từ phù hợp là “契合”, đọc là qìhé. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-13-q07','seed-hsk8-13',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “脉络 — màiluò”, nghĩa là “mạch phát triển”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-13-q08','seed-hsk8-13',8,'single_choice','Từ “审视” gần nghĩa nhất với phương án nào?','“审视” (shěnshì) có nghĩa là “xem xét kỹ”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 8.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-13-q09','seed-hsk8-13',9,'single_choice','Pinyin phù hợp với “介入” là phương án nào?','Pinyin của “介入” là “jièrù”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “can thiệp”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-13-q10','seed-hsk8-13',10,'single_choice','Chọn từ Hán ngữ có nghĩa “kiến tạo”.','Từ phù hợp là “建构”, đọc là jiàngòu. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-13-q11','seed-hsk8-13',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “边界 — biānjiè”, nghĩa là “ranh giới”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-13-q12','seed-hsk8-13',12,'single_choice','Từ “内涵” gần nghĩa nhất với phương án nào?','“内涵” (nèihán) có nghĩa là “nội hàm”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 8.',NULL,NULL,0,1,'',datetime('now')),
