('seed-hsk8-13-q37','seed-hsk8-13',37,'single_choice','Pinyin phù hợp với “诠释” là phương án nào?','Pinyin của “诠释” là “quánshì”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “diễn giải”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-13-q38','seed-hsk8-13',38,'single_choice','Chọn từ Hán ngữ có nghĩa “cân nhắc”.','Từ phù hợp là “权衡”, đọc là quánhéng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-13-q39','seed-hsk8-13',39,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “外延 — wàiyán”, nghĩa là “ngoại diên”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-13-q40','seed-hsk8-13',40,'single_choice','Từ “衔接” gần nghĩa nhất với phương án nào?','“衔接” (xiánjiē) có nghĩa là “kết nối chuyển tiếp”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 8.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-13-q41','seed-hsk8-13',41,'single_choice','Pinyin phù hợp với “论证” là phương án nào?','Pinyin của “论证” là “lùnzhèng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “lập luận chứng minh”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-13-q42','seed-hsk8-13',42,'single_choice','Chọn từ Hán ngữ có nghĩa “nhu cầu/đòi hỏi”.','Từ phù hợp là “诉求”, đọc là sùqiú. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-13-q43','seed-hsk8-13',43,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “范式 — fànshì”, nghĩa là “mô thức”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-13-q44','seed-hsk8-13',44,'single_choice','Từ “推演” gần nghĩa nhất với phương án nào?','“推演” (tuīyǎn) có nghĩa là “suy diễn”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 8.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-13-q45','seed-hsk8-13',45,'single_choice','Pinyin phù hợp với “抽象” là phương án nào?','Pinyin của “抽象” là “chōuxiàng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “trừu tượng”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-13-q46','seed-hsk8-13',46,'single_choice','Chọn từ Hán ngữ có nghĩa “phù hợp”.','Từ phù hợp là “契合”, đọc là qìhé. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-13-q47','seed-hsk8-13',47,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “脉络 — màiluò”, nghĩa là “mạch phát triển”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-13-q48','seed-hsk8-13',48,'single_choice','Từ “审视” gần nghĩa nhất với phương án nào?','“审视” (shěnshì) có nghĩa là “xem xét kỹ”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 8.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-13-q49','seed-hsk8-13',49,'single_choice','Pinyin phù hợp với “介入” là phương án nào?','Pinyin của “介入” là “jièrù”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “can thiệp”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-13-q50','seed-hsk8-13',50,'single_choice','Chọn từ Hán ngữ có nghĩa “kiến tạo”.','Từ phù hợp là “建构”, đọc là jiàngòu. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now'));
