('seed-hsk8-14-q40','seed-hsk8-14',40,'single_choice','Từ “介入” gần nghĩa nhất với phương án nào?','“介入” (jièrù) có nghĩa là “can thiệp”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 8.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-14-q41','seed-hsk8-14',41,'single_choice','Pinyin phù hợp với “建构” là phương án nào?','Pinyin của “建构” là “jiàngòu”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “kiến tạo”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-14-q42','seed-hsk8-14',42,'single_choice','Chọn từ Hán ngữ có nghĩa “ranh giới”.','Từ phù hợp là “边界”, đọc là biānjiè. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-14-q43','seed-hsk8-14',43,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “内涵 — nèihán”, nghĩa là “nội hàm”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-14-q44','seed-hsk8-14',44,'single_choice','Từ “辨析” gần nghĩa nhất với phương án nào?','“辨析” (biànxī) có nghĩa là “phân biệt và phân tích”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 8.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-14-q45','seed-hsk8-14',45,'single_choice','Pinyin phù hợp với “表征” là phương án nào?','Pinyin của “表征” là “biǎozhēng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “biểu trưng”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-14-q46','seed-hsk8-14',46,'single_choice','Chọn từ Hán ngữ có nghĩa “định hướng”.','Từ phù hợp là “取向”, đọc là qǔxiàng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-14-q47','seed-hsk8-14',47,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “回应 — huíyìng”, nghĩa là “phản hồi”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-14-q48','seed-hsk8-14',48,'single_choice','Từ “诠释” gần nghĩa nhất với phương án nào?','“诠释” (quánshì) có nghĩa là “diễn giải”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 8.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-14-q49','seed-hsk8-14',49,'single_choice','Pinyin phù hợp với “权衡” là phương án nào?','Pinyin của “权衡” là “quánhéng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “cân nhắc”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-14-q50','seed-hsk8-14',50,'single_choice','Chọn từ Hán ngữ có nghĩa “ngoại diên”.','Từ phù hợp là “外延”, đọc là wàiyán. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now'));
