INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk8-15','HSK8-15','HSK 8 · Đề 15','hsk','HSK 8',90,'published',1,'Đề luyện HSK 8 số 15 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk8-15-q01','seed-hsk8-15',1,'single_choice','Pinyin phù hợp với “外延” là phương án nào?','Pinyin của “外延” là “wàiyán”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “ngoại diên”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-15-q02','seed-hsk8-15',2,'single_choice','Chọn từ Hán ngữ có nghĩa “kết nối chuyển tiếp”.','Từ phù hợp là “衔接”, đọc là xiánjiē. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-15-q03','seed-hsk8-15',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “论证 — lùnzhèng”, nghĩa là “lập luận chứng minh”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-15-q04','seed-hsk8-15',4,'single_choice','Từ “诉求” gần nghĩa nhất với phương án nào?','“诉求” (sùqiú) có nghĩa là “nhu cầu/đòi hỏi”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 8.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-15-q05','seed-hsk8-15',5,'single_choice','Pinyin phù hợp với “范式” là phương án nào?','Pinyin của “范式” là “fànshì”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “mô thức”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-15-q06','seed-hsk8-15',6,'single_choice','Chọn từ Hán ngữ có nghĩa “suy diễn”.','Từ phù hợp là “推演”, đọc là tuīyǎn. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-15-q07','seed-hsk8-15',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “抽象 — chōuxiàng”, nghĩa là “trừu tượng”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-15-q08','seed-hsk8-15',8,'single_choice','Từ “契合” gần nghĩa nhất với phương án nào?','“契合” (qìhé) có nghĩa là “phù hợp”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 8.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-15-q09','seed-hsk8-15',9,'single_choice','Pinyin phù hợp với “脉络” là phương án nào?','Pinyin của “脉络” là “màiluò”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “mạch phát triển”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-15-q10','seed-hsk8-15',10,'single_choice','Chọn từ Hán ngữ có nghĩa “xem xét kỹ”.','Từ phù hợp là “审视”, đọc là shěnshì. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-15-q11','seed-hsk8-15',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “介入 — jièrù”, nghĩa là “can thiệp”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-15-q12','seed-hsk8-15',12,'single_choice','Từ “建构” gần nghĩa nhất với phương án nào?','“建构” (jiàngòu) có nghĩa là “kiến tạo”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 8.',NULL,NULL,0,1,'',datetime('now')),
