('seed-hsk8-15-q43','seed-hsk8-15',43,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “论证 — lùnzhèng”, nghĩa là “lập luận chứng minh”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-15-q44','seed-hsk8-15',44,'single_choice','Từ “诉求” gần nghĩa nhất với phương án nào?','“诉求” (sùqiú) có nghĩa là “nhu cầu/đòi hỏi”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 8.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-15-q45','seed-hsk8-15',45,'single_choice','Pinyin phù hợp với “范式” là phương án nào?','Pinyin của “范式” là “fànshì”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “mô thức”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-15-q46','seed-hsk8-15',46,'single_choice','Chọn từ Hán ngữ có nghĩa “suy diễn”.','Từ phù hợp là “推演”, đọc là tuīyǎn. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-15-q47','seed-hsk8-15',47,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “抽象 — chōuxiàng”, nghĩa là “trừu tượng”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-15-q48','seed-hsk8-15',48,'single_choice','Từ “契合” gần nghĩa nhất với phương án nào?','“契合” (qìhé) có nghĩa là “phù hợp”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 8.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-15-q49','seed-hsk8-15',49,'single_choice','Pinyin phù hợp với “脉络” là phương án nào?','Pinyin của “脉络” là “màiluò”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “mạch phát triển”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-15-q50','seed-hsk8-15',50,'single_choice','Chọn từ Hán ngữ có nghĩa “xem xét kỹ”.','Từ phù hợp là “审视”, đọc là shěnshì. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now'));
