('seed-hsk8-16-q46','seed-hsk8-16',46,'single_choice','Chọn từ Hán ngữ có nghĩa “phân biệt và phân tích”.','Từ phù hợp là “辨析”, đọc là biànxī. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-16-q47','seed-hsk8-16',47,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “表征 — biǎozhēng”, nghĩa là “biểu trưng”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-16-q48','seed-hsk8-16',48,'single_choice','Từ “取向” gần nghĩa nhất với phương án nào?','“取向” (qǔxiàng) có nghĩa là “định hướng”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 8.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-16-q49','seed-hsk8-16',49,'single_choice','Pinyin phù hợp với “回应” là phương án nào?','Pinyin của “回应” là “huíyìng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “phản hồi”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-16-q50','seed-hsk8-16',50,'single_choice','Chọn từ Hán ngữ có nghĩa “diễn giải”.','Từ phù hợp là “诠释”, đọc là quánshì. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now'));
