INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk8-20','HSK8-20','HSK 8 · Đề 20','hsk','HSK 8',90,'published',1,'Đề luyện HSK 8 số 20 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk8-20-q01','seed-hsk8-20',1,'single_choice','Pinyin phù hợp với “推演” là phương án nào?','Pinyin của “推演” là “tuīyǎn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “suy diễn”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-20-q02','seed-hsk8-20',2,'single_choice','Chọn từ Hán ngữ có nghĩa “trừu tượng”.','Từ phù hợp là “抽象”, đọc là chōuxiàng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-20-q03','seed-hsk8-20',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “契合 — qìhé”, nghĩa là “phù hợp”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-20-q04','seed-hsk8-20',4,'single_choice','Từ “脉络” gần nghĩa nhất với phương án nào?','“脉络” (màiluò) có nghĩa là “mạch phát triển”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 8.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-20-q05','seed-hsk8-20',5,'single_choice','Pinyin phù hợp với “审视” là phương án nào?','Pinyin của “审视” là “shěnshì”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “xem xét kỹ”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-20-q06','seed-hsk8-20',6,'single_choice','Chọn từ Hán ngữ có nghĩa “can thiệp”.','Từ phù hợp là “介入”, đọc là jièrù. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-20-q07','seed-hsk8-20',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “建构 — jiàngòu”, nghĩa là “kiến tạo”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-20-q08','seed-hsk8-20',8,'single_choice','Từ “边界” gần nghĩa nhất với phương án nào?','“边界” (biānjiè) có nghĩa là “ranh giới”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 8.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-20-q09','seed-hsk8-20',9,'single_choice','Pinyin phù hợp với “内涵” là phương án nào?','Pinyin của “内涵” là “nèihán”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “nội hàm”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-20-q10','seed-hsk8-20',10,'single_choice','Chọn từ Hán ngữ có nghĩa “phân biệt và phân tích”.','Từ phù hợp là “辨析”, đọc là biànxī. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-20-q11','seed-hsk8-20',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “表征 — biǎozhēng”, nghĩa là “biểu trưng”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-20-q12','seed-hsk8-20',12,'single_choice','Từ “取向” gần nghĩa nhất với phương án nào?','“取向” (qǔxiàng) có nghĩa là “định hướng”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 8.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk8-20-q13','seed-hsk8-20',13,'single_choice','Pinyin phù hợp với “回应” là phương án nào?','Pinyin của “回应” là “huíyìng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “phản hồi”.',NULL,NULL,0,1,'',datetime('now')),
